CREATE PROCEDURE [sync].[gsp_ClientSelectUpdateConflicts_tblCompanies]
@CompanyGuid uniqueidentifier
AS
BEGIN
    -- This command is used if @sync_row_count returns
    -- 0 when changes are applied to the server.
    --
    SELECT [dbo].[tblCompanies].[ID],[dbo].[tblCompanies].[Code],[dbo].[tblCompanies].[Name],[dbo].[tblCompanies].[ShortName],[dbo].[tblCompanies].[Address1],[dbo].[tblCompanies].[Address2],[dbo].[tblCompanies].[City],[dbo].[tblCompanies].[State],[dbo].[tblCompanies].[Zip],[dbo].[tblCompanies].[Country],[dbo].[tblCompanies].[Phone],[dbo].[tblCompanies].[FAX],[dbo].[tblCompanies].[EmergencyContact],[dbo].[tblCompanies].[EmergencyPhone],[dbo].[tblCompanies].[FlightPrefix],[dbo].[tblCompanies].[EffectiveDate],[dbo].[tblCompanies].[ExpirationDate],[dbo].[tblCompanies].[OnHold],[dbo].[tblCompanies].[PickupFLights],[dbo].[tblCompanies].[StockTrack],[dbo].[tblCompanies].[SufferLossGain],[dbo].[tblCompanies].[LowStockWarning],[dbo].[tblCompanies].[LockedOut],[dbo].[tblCompanies].[LockedOutReason],[dbo].[tblCompanies].[LockedOutDate],[dbo].[tblCompanies].[ReceivableAccount],[dbo].[tblCompanies].[RefinerCode],[dbo].[tblCompanies].[LastActivityDate],[dbo].[tblCompanies].[CreditOK],[dbo].[tblCompanies].[AdditiveAccounting],[dbo].[tblCompanies].[PurchaseOrderRequired],[dbo].[tblCompanies].[EPANumber],[dbo].[tblCompanies].[FederalID],[dbo].[tblCompanies].[FederalID2],[dbo].[tblCompanies].[FederalID3],[dbo].[tblCompanies].[FederalID4],[dbo].[tblCompanies].[FederalID5],[dbo].[tblCompanies].[StateID],[dbo].[tblCompanies].[TaxNumber],[dbo].[tblCompanies].[FlushPermitted],[dbo].[tblCompanies].[PumpOffPermitted],[dbo].[tblCompanies].[DeliveryToTerminalPermitted],[dbo].[tblCompanies].[LicenseNumber],[dbo].[tblCompanies].[LicenseExpiration],[dbo].[tblCompanies].[InsuranceCompany],[dbo].[tblCompanies].[InsurancePolicy],[dbo].[tblCompanies].[LiabilityAmount],[dbo].[tblCompanies].[HazardousMaterialExclusion],[dbo].[tblCompanies].[InsuranceExpiration],[dbo].[tblCompanies].[AllowDriverEntry],[dbo].[tblCompanies].[PINRequired],[dbo].[tblCompanies].[MaximumVehicleWeight],[dbo].[tblCompanies].[WeightUnits],[dbo].[tblCompanies].[AccountNumber],[dbo].[tblCompanies].[SCACCode],[dbo].[tblCompanies].[DisableOwnerAllocationsCheck],[dbo].[tblCompanies].[DisableShipperAllocationsCheck],[dbo].[tblCompanies].[DisableBillToAllocationsCheck],[dbo].[tblCompanies].[DisableShipToAllocationsCheck],[dbo].[tblCompanies].[LoadRackDisplayText],[dbo].[tblCompanies].[UserData1],[dbo].[tblCompanies].[UserData2],[dbo].[tblCompanies].[UserData3],[dbo].[tblCompanies].[UserData4],[dbo].[tblCompanies].[UserData5],[dbo].[tblCompanies].[UserData6],[dbo].[tblCompanies].[UserData7],[dbo].[tblCompanies].[UserData8],[dbo].[tblCompanies].[CreatedDate],[dbo].[tblCompanies].[CreatedBy],[dbo].[tblCompanies].[UpdatedDate],[dbo].[tblCompanies].[UpdatedBy],[dbo].[tblCompanies].[CompanyGuid],[dbo].[tblCompanies].[SiteGuid],[dbo].[tblCompanies].[IATAGuid],[dbo].[tblCompanies].[ShipperTypeApplicationStringGuid],[dbo].[tblCompanies].[CustomerBillToTypeApplicationStringGuid],[dbo].[tblCompanies].[CustomerShipToTypeApplicationStringGuid],[dbo].[tblCompanies].[Contact1Name],[dbo].[tblCompanies].[Contact1Address1],[dbo].[tblCompanies].[Contact1Address2],[dbo].[tblCompanies].[Contact1City],[dbo].[tblCompanies].[Contact1State],[dbo].[tblCompanies].[Contact1Zip],[dbo].[tblCompanies].[Contact1Country],[dbo].[tblCompanies].[Contact1PhoneOffice],[dbo].[tblCompanies].[Contact1Fax],[dbo].[tblCompanies].[Contact1EmailAddress],[dbo].[tblCompanies].[Contact2Name],[dbo].[tblCompanies].[Contact2Address1],[dbo].[tblCompanies].[Contact2Address2],[dbo].[tblCompanies].[Contact2City],[dbo].[tblCompanies].[Contact2State],[dbo].[tblCompanies].[Contact2Zip],[dbo].[tblCompanies].[Contact2Country],[dbo].[tblCompanies].[Contact2PhoneOffice],[dbo].[tblCompanies].[Contact2Fax],[dbo].[tblCompanies].[Contact2EmailAddress],[dbo].[tblCompanies].[Contact1PhoneMobile],[dbo].[tblCompanies].[Contact2PhoneMobile],[dbo].[tblCompanies].[_MasterRecordGuid],[dbo].[tblCompanies].[Note],[dbo].[tblCompanies].[HiddenDate],[dbo].[tblCompanies].[ScullyRequired],[dbo].[tblCompanies].[ConsortiumTypeIndex],[dbo].[tblCompanies].[CompanyIATACode],[dbo].